DROP DATABASE IF EXISTS cacao_curimana;
CREATE DATABASE cacao_curimana CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cacao_curimana;

CREATE TABLE roles(id_rol TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(30) NOT NULL UNIQUE) ENGINE=InnoDB;
INSERT INTO roles(nombre) VALUES('ADMINISTRADOR'),('SUPERVISOR'),('TECNICO');

CREATE TABLE usuarios(id_usuario INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,usuario VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,id_rol TINYINT UNSIGNED NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_usuarios_roles FOREIGN KEY(id_rol) REFERENCES roles(id_rol)) ENGINE=InnoDB;

CREATE TABLE tecnicos(id_tecnico INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_usuario INT UNSIGNED NULL UNIQUE,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,cargo VARCHAR(100) NOT NULL,telefono VARCHAR(20),email VARCHAR(120),activo TINYINT(1) NOT NULL DEFAULT 1,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_tecnicos_usuario FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario)) ENGINE=InnoDB;

CREATE TABLE caserios(id_caserio INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,distrito VARCHAR(120) NOT NULL DEFAULT 'Curimana',provincia VARCHAR(120) NOT NULL DEFAULT 'Padre Abad',departamento VARCHAR(120) NOT NULL DEFAULT 'Ucayali',observacion VARCHAR(255),activo TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_caserio(nombre,distrito)) ENGINE=InnoDB;

CREATE TABLE beneficiarios(id_beneficiario INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,dni VARCHAR(12),telefono VARCHAR(20),id_caserio INT UNSIGNED NOT NULL,sector VARCHAR(120),referencia VARCHAR(255),activo TINYINT(1) NOT NULL DEFAULT 1,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_dni(dni),CONSTRAINT fk_beneficiario_caserio FOREIGN KEY(id_caserio) REFERENCES caserios(id_caserio)) ENGINE=InnoDB;

CREATE TABLE parcelas(id_parcela INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_beneficiario INT UNSIGNED NOT NULL,nombre_predio VARCHAR(120),cultivo VARCHAR(80) NOT NULL DEFAULT 'Cacao',area_ha DECIMAL(8,2),latitud DECIMAL(10,7),longitud DECIMAL(10,7),observacion TEXT,activo TINYINT(1) NOT NULL DEFAULT 1,CONSTRAINT fk_parcela_beneficiario FOREIGN KEY(id_beneficiario) REFERENCES beneficiarios(id_beneficiario)) ENGINE=InnoDB;

CREATE TABLE visitas(id_visita BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fecha DATE NOT NULL,id_tecnico INT UNSIGNED NOT NULL,id_beneficiario INT UNSIGNED NOT NULL,id_parcela INT UNSIGNED NULL,tipo_visita ENUM('ASISTENCIA_TECNICA','SUPERVISION') NOT NULL DEFAULT 'SUPERVISION',objetivo TEXT NOT NULL,latitud DECIMAL(10,7),longitud DECIMAL(10,7),observacion TEXT,id_usuario_registro INT UNSIGNED NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_visita_tecnico FOREIGN KEY(id_tecnico) REFERENCES tecnicos(id_tecnico),CONSTRAINT fk_visita_beneficiario FOREIGN KEY(id_beneficiario) REFERENCES beneficiarios(id_beneficiario),CONSTRAINT fk_visita_parcela FOREIGN KEY(id_parcela) REFERENCES parcelas(id_parcela),CONSTRAINT fk_visita_usuario FOREIGN KEY(id_usuario_registro) REFERENCES usuarios(id_usuario),INDEX idx_visita_fecha(fecha)) ENGINE=InnoDB;

CREATE TABLE supervisiones(id_supervision BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_visita BIGINT UNSIGNED NOT NULL,actividad_programada TEXT NOT NULL,cumplimiento ENUM('CUMPLIDO','PARCIAL','NO_CUMPLIDO') NOT NULL,observacion TEXT,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_supervision_visita FOREIGN KEY(id_visita) REFERENCES visitas(id_visita) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE hallazgos(id_hallazgo BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_supervision BIGINT UNSIGNED NOT NULL,descripcion TEXT NOT NULL,nivel ENUM('BAJO','MEDIO','ALTO') NOT NULL DEFAULT 'MEDIO',creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_hallazgo_supervision FOREIGN KEY(id_supervision) REFERENCES supervisiones(id_supervision) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE recomendaciones(id_recomendacion BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_supervision BIGINT UNSIGNED NOT NULL,descripcion TEXT NOT NULL,responsable VARCHAR(150),fecha_limite DATE,estado ENUM('PENDIENTE','EN_PROCESO','CUMPLIDO') NOT NULL DEFAULT 'PENDIENTE',creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_recomendacion_supervision FOREIGN KEY(id_supervision) REFERENCES supervisiones(id_supervision) ON DELETE CASCADE,INDEX idx_rec_estado(estado),INDEX idx_rec_fecha(fecha_limite)) ENGINE=InnoDB;

CREATE TABLE seguimientos(id_seguimiento BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_recomendacion BIGINT UNSIGNED NOT NULL,fecha DATE NOT NULL,estado_anterior ENUM('PENDIENTE','EN_PROCESO','CUMPLIDO') NOT NULL,estado_nuevo ENUM('PENDIENTE','EN_PROCESO','CUMPLIDO') NOT NULL,observacion TEXT,id_usuario INT UNSIGNED NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_seg_recomendacion FOREIGN KEY(id_recomendacion) REFERENCES recomendaciones(id_recomendacion) ON DELETE CASCADE,CONSTRAINT fk_seg_usuario FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario)) ENGINE=InnoDB;

INSERT INTO caserios(nombre) VALUES('Curimana');
